// The few texts Bookworm Adventures keeps in its exe rather than in its scripts and properties (the loading
// screen's letters, error messages). port: by the user's decision (2026-10-19) no game text is in the
// repository: the port reads each of them at start-up from the player's own BookwormAdventures.exe, by address.
//
// - GameTextTable.inc (generated by games/bookwormadv2/tools/gametext.py from the GT(...) uses in the sources)
//   lists each string's address in the game image, its length and a hash: no text.
// - LoadGameTexts() reads each text at its address and checks length and hash. A text that does not match
//   (another version of the exe) stays empty and is logged.
// - Code names a text by its address in the original: GT(0x007aa8fc). Overrides: any string property named
//   GT_<8 hex digits> (from the game's properties or a mod) replaces the text read from the exe.
#pragma once

#include "Common.h"

namespace Sexy {

// Reads the texts from the game folder's executable and applies the string-property overrides. Returns
// false when the executable is missing or no text matched.
bool LoadGameTexts();
// The text the original keeps at theVA; "" for an address that is not in the table
const SexyString& GameText(unsigned int theVA);

#define GT(theVA) (::Sexy::GameText(theVA))
#define GTC(theVA) (::Sexy::GameText(theVA).c_str())
// A text's address kept in a table, for GT later (gametext.py finds these too)
#define GTA(theVA) (theVA)

}  // namespace Sexy
